import pathlib, os, shutil, subprocess, time, json

def do_case(files):
    base="/tmp/ordtest"
    if pathlib.Path(base).exists():
        shutil.rmtree(base)
    pathlib.Path(base).mkdir()
    for fname, lines in files.items():
        p=pathlib.Path(base)/fname
        p.parent.mkdir(parents=True, exist_ok=True)
        with open(p,'w') as f:
            for l in lines:
                f.write(l+"\n")
    out_raw=subprocess.run(["./executable","--color","no","--silent-load","-o","raw",base], capture_output=True, text=True)
    raw=out_raw.stdout.strip().splitlines()
    raw_paths=[]
    for line in raw:
        try:
            segs=line.split('"')
            req=segs[1]
            path=req.split()[1]
            raw_paths.append(path)
        except:
            raw_paths.append(line)
    out_json=subprocess.run(["./executable","--color","no","--silent-load","-o","json",base], capture_output=True, text=True)
    try:
        j=json.loads(out_json.stdout)
        jpaths=[e['path'] for e in j]
    except:
        jpaths=[]
    out_csv=subprocess.run(["./executable","--color","no","--silent-load","-o","csv",base], capture_output=True, text=True)
    csv_lines=out_csv.stdout.strip().splitlines()[1:]
    csv_paths=[]
    for line in csv_lines:
        parts=line.split(',')
        if len(parts)>=5:
            csv_paths.append(parts[4].strip('"'))
    print(f"Case files={files}")
    print(f"  raw_paths={raw_paths}")
    print(f"  json_paths={jpaths}")
    print(f"  csv_paths={csv_paths}")
    print()

def log(path,date):
    return f'127.0.0.1 - - [{date}:10:00:00 +0000] "GET {path} HTTP/1.1" 200 1 "-" "M"'

# Case A again with clean
do_case({
    "f1-access.log": [log("/21","21/Jan/2021"), log("/23","23/Jan/2021")],
    "f2-access.log": [log("/22","22/Jan/2021")]
})

# Case B
do_case({
    "f1-access.log": [log("/23","23/Jan/2021"), log("/21","21/Jan/2021")],
    "f2-access.log": [log("/22","22/Jan/2021")]
})

# Case C 3 files
do_case({
    "f1-access.log": [log("/23","23/Jan/2021")],
    "f2-access.log": [log("/21","21/Jan/2021")],
    "f3-access.log": [log("/22","22/Jan/2021")]
})

# Single file unsorted
do_case({
    "access.log": [log("/23","23/Jan/2021"), log("/21","21/Jan/2021"), log("/22","22/Jan/2021")]
})

# Single file unsorted reverse
do_case({
    "access.log": [log("/22","22/Jan/2021"), log("/23","23/Jan/2021"), log("/21","21/Jan/2021")]
})

# Two files each 2 lines interleaved
do_case({
    "f1-access.log": [log("/21","21/Jan/2021"), log("/23","23/Jan/2021")],
    "f2-access.log": [log("/22","22/Jan/2021"), log("/20","20/Jan/2021")]
})

do_case({
    "f1-access.log": [log("/23","23/Jan/2021"), log("/21","21/Jan/2021")],
    "f2-access.log": [log("/22","22/Jan/2021"), log("/20","20/Jan/2021")]
})

# Multi files with same date different times
def logt(path,date,time):
    return f'127.0.0.1 - - [{date}:{time} +0000] "GET {path} HTTP/1.1" 200 1 "-" "M"'

do_case({
