// ---------- Log parsing ----------

#[derive(Debug, Clone)]
struct LogEntry {
    date: NaiveDate, // day
    date_str: String, // "2021/01/21"
    time_str: String, // "05:49:52"
    time_of_day: (u32,u32,u32), // h,m,s
    remote_addr: String,
    method: String, // normalized: uppercase known or "other" or "none"
    method_raw: String, // original method candidate? For display? Use normalized
    path: String,
    status: u16,
    status_str: String,
    bytes: u64,
    referer: String,
    raw_line: String,
}

static KNOWN_METHODS: &[&str] = &["GET","POST","PUT","DELETE","HEAD","OPTIONS","PATCH","CONNECT","TRACE"];

fn parse_log_line(line: &str) -> Option<LogEntry> {
    // Regex: ^(\S+) \S+ \S+ \[([^\]]+)\] "([^"]*)" (\d+) (\S+) "([^"]*)" "([^"]*)".*
    // We'll compile each time? Better static.
    // Using regex crate
    // For performance, we can attempt manual parsing but use regex for simplicity.
    // Let's build regex lazily via once_cell? We'll just compile once per call using lazy_static? Simpler: use regex static via lazy.
    // We'll have a global Regex via once_cell::sync::Lazy which is available in std? In Rust 1.92, OnceLock is available.
    use std::sync::OnceLock;
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| {
        Regex::new(r#"^(\S+) \S+ \S+ \[([^\]]+)\] "([^"]*)" (\d+) (\S+) "([^"]*)" "([^"]*)"#).unwrap()
    });
    let caps = re.captures(line)?;
    let remote_addr = caps.get(1)?.as_str().to_string();
    let time_local = caps.get(2)?.as_str(); // 21/Jan/2021:05:49:52 +0000
    let request = caps.get(3)?.as_str();
    let status_s = caps.get(4)?.as_str();
    let bytes_s = caps.get(5)?.as_str();
    let referer = caps.get(6)?.as_str().to_string();
    // let user_agent = caps.get(7)

    // parse status
    let status: u16 = status_s.parse().ok()?;
    let bytes: u64 = if bytes_s == "-" {
        // In original, dash makes line invalid (NoLogFileFound if all dash). So we treat as None => fail
        // But earlier test with access.log containing dash and valid line: dash line was ignored, valid counted. So we return None for dash.
        return None;
    } else {
        bytes_s.parse().ok()?
    };

    // parse time_local: format dd/MMM/yyyy:HH:mm:ss +zzzz
    // Example: 21/Jan/2021:05:49:52 +0000
    // We need date and time
    // Split at ' '
    // first part before space contains day/month/year:time
    // Use regex: (\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+)
    static TIME_RE: OnceLock<Regex> = OnceLock::new();
    let tre = TIME_RE.get_or_init(|| {
        Regex::new(r#"^(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+)"#).unwrap()
    });
    let tcap = tre.captures(time_local)?;
    let day: u32 = tcap.get(1)?.as_str().parse().ok()?;
    let mon_str = tcap.get(2)?.as_str();
    let year: i32 = tcap.get(3)?.as_str().parse().ok()?;
    let hour: u32 = tcap.get(4)?.as_str().parse().ok()?;
    let minute: u32 = tcap.get(5)?.as_str().parse().ok()?;
    let second: u32 = tcap.get(6)?.as_str().parse().ok()?;

    let month = match mon_str {
        "Jan" => 1,
        "Feb" => 2,
        "Mar" => 3,
        "Apr" => 4,
        "May" => 5,
        "Jun" => 6,
        "Jul" => 7,
        "Aug" => 8,
        "Sep" => 9,
        "Oct" => 10,
        "Nov" => 11,
        "Dec" => 12,
        _ => return None,
    };
    let date = NaiveDate::from_ymd_opt(year, month, day)?;
    let date_str = format!("{:04}/{:02}/{:02}", year, month, day);
    let time_str = format!("{:02}:{:02}:{:02}", hour, minute, second);

    // parse request
    let (method, path) = if request == "-" || request.is_empty() {
        ("none".to_string(), "-".to_string())
    } else {
        let parts: Vec<&str> = request.split_whitespace().collect();
        if parts.len() == 1 {
            // only one token -> method none, path token
            ("none".to_string(), parts[0].to_string())
        } else if parts.len() >= 2 {
            let meth_candidate = parts[0];
            let path_candidate = parts[1];
            // Check known
            let meth_norm = if KNOWN_METHODS.contains(&meth_candidate) {
                meth_candidate.to_string()
            } else {
                // If candidate looks like known? Actually if not known, it's "other"
                // But also if candidate is something else? According to tests, "FOO" -> other, "BADREQUEST" single token -> none, but "FOO" with path -> other
                // So for len>=2, method = other if not known
                "other".to_string()
            };
            // However, what about method "none"? That shouldn't happen because request would be "-" case.
            // For path, it's second token
            (meth_norm, path_candidate.to_string())
        } else {
            ("none".to_string(), "-".to_string())
        }
    };

    // Special: method extraction earlier test with "GET" alone gave none, path GET. Our logic for len==1 returns none, path token => matches.
    // For "BADREQUEST" alone => none, path BADREQUEST => matches earlier observation (method none, path BADREQUEST)
    // For "FOO /j HTTP/1.1": parts = ["FOO","/j","HTTP/1.1"] => method other, path /j => matches.
    // For "-": we handled.
