// ----- LogEntry -----
#[derive(Debug, Clone)]
struct LogEntry {
    date: NaiveDate,
    date_str: String,
    time_str: String,
    time_secs: u32,
    remote_addr: String,
    method: String,
    path: String,
    status: u16,
    bytes: u64,
    referer: String,
    raw_line: String,
}

static KNOWN_METHODS: &[&str] = &["GET","POST","PUT","DELETE","HEAD","OPTIONS","PATCH","CONNECT","TRACE"];

fn parse_log_line(line: &str) -> Option<LogEntry> {
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| {
        Regex::new(r#"^(\S+) \S+ \S+ \[([^\]]+)\] "([^"]*)" (\d+) (\S+) "([^"]*)" "([^"]*)"#).unwrap()
    });
    let caps = re.captures(line)?;
    let remote_addr = caps.get(1)?.as_str().to_string();
    let time_local = caps.get(2)?.as_str();
    let request = caps.get(3)?.as_str();
    let status_s = caps.get(4)?.as_str();
    let bytes_s = caps.get(5)?.as_str();
    let referer = caps.get(6)?.as_str().to_string();

    let status: u16 = status_s.parse().ok()?;
    if bytes_s == "-" {
        return None;
    }
    let bytes: u64 = bytes_s.parse().ok()?;

    static TIME_RE: OnceLock<Regex> = OnceLock::new();
    let tre = TIME_RE.get_or_init(|| {
        Regex::new(r#"^(\d+)/(\w+)/(\d+):(\d+):(\d+):(\d+)"#).unwrap()
    });
    let tcap = tre.captures(time_local)?;
    let day: u32 = tcap.get(1)?.as_str().parse().ok()?;
    let mon_str = tcap.get(2)?.as_str();
    let year: i32 = tcap.get(3)?.as_str().parse().ok()?;
    let hour: u32 = tcap.get(4)?.as_str().parse().ok()?;
    let minute: u32 = tcap.get(5)?.as_str().parse().ok()?;
    let second: u32 = tcap.get(6)?.as_str().parse().ok()?;
    let month = match mon_str {
        "Jan"=>1,"Feb"=>2,"Mar"=>3,"Apr"=>4,"May"=>5,"Jun"=>6,"Jul"=>7,"Aug"=>8,"Sep"=>9,"Oct"=>10,"Nov"=>11,"Dec"=>12,_=>return None,
    };
    let date = NaiveDate::from_ymd_opt(year, month, day)?;
    let date_str = format!("{:04}/{:02}/{:02}", year, month, day);
    let time_str = format!("{:02}:{:02}:{:02}", hour, minute, second);
    let time_secs = hour*3600+minute*60+second;

    let (method, path) = if request == "-" || request.is_empty() {
        ("none".to_string(), "-".to_string())
    } else {
        let parts: Vec<&str> = request.split_whitespace().collect();
        if parts.len() == 1 {
            ("none".to_string(), parts[0].to_string())
        } else {
            let meth = parts[0];
            let p = parts[1];
            let norm = if KNOWN_METHODS.contains(&meth) { meth.to_string() } else { "other".to_string() };
            (norm, p.to_string())
        }
    };

    Some(LogEntry {
        date,
        date_str,
        time_str,
        time_secs,
        remote_addr,
        method,
        path,
        status,
        bytes,
        referer,
        raw_line: line.to_string(),
    })
}

// ----- bytes formatting -----
fn format_bytes(b: u64) -> String {
    if b < 10000 {
        return format!("{}", b);
    }
    if b < 999500 {
        // K with Rust formatting {:.0} (bankers)
        let k = b as f64 / 1000.0;
        let s = format!("{:.0}", k);
        return format!("{}K", s);
    }
    if b < 1_000_000_000 {
        let m = b as f64 / 1_000_000.0;
        if b < 10_000_000 {
            let s = format!("{:.1}", m);
            return format!("{}M", s);
        } else {
            let s = format!("{:.0}", m);
            return format!("{}M", s);
        }
    } else {
        let g = b as f64 / 1_000_000_000.0;
        if b < 10_000_000_000 {
            let s = format!("{:.1}", g);
            return format!("{}G", s);
        } else {
            let s = format!("{:.0}", g);
            return format!("{}G", s);
        }
    }
}

// ----- File reading -----
fn read_file_lines(path: &Path) -> Result<Vec<String>, MyError> {
    // decide if gz
    let fname = path.file_name().and_then(|s| s.to_str()).unwrap_or("");
    // case sensitive .gz check
    if fname.ends_with(".gz") {
        // try to open as gz
        let f = fs::File::open(path).map_err(|e| MyError::Io(e))?;
        let mut decoder = flate2::read::GzDecoder::new(f);
        // we need to read and detect invalid header: GzDecoder will error on header.
        // To replicate original error message for invalid gzip header, we need to attempt to read?
        // The error "invalid gzip header" comes from flate2's custom error.
        // We'll try to read first bytes.
        let mut buf = Vec::new();
        match decoder.read_to_end(&mut buf) {
            Ok(_) => {
                // successfully decompressed, now we have bytes, try to convert to utf8 lines.
                let text = String::from_utf8(buf).map_err(|_| MyError::Io(io::Error::new(io::ErrorKind::InvalidData, "stream did not contain valid UTF-8")))?;
                Ok(text.lines().map(|l| l.to_string()).collect())
            }
            Err(e) => {
                // Check if error is invalid gzip header
                // flate2 error message exactly "invalid gzip header" comes as custom.
                // We need to propagate as Io with that message.
                Err(MyError::Io(e))
            }
        }
    } else {
        let f = fs::File::open(path).map_err(|e| MyError::Io(e))?;
        let reader = BufReader::new(f);
        let mut lines = Vec::new();
        for line in reader.lines() {
            let l = line.map_err(|e| MyError::Io(e))?;
            lines.push(l);
        }
        Ok(lines)
    }
}

fn collect_file_paths(inputs: &[String], no_name_check: bool) -> Result<Vec<PathBuf>, MyError> {
    if inputs.is_empty() {
        let default = Path::new("/var/log/nginx");
        if !default.exists() {
            return Err(MyError::PathNotFound(default.to_string_lossy().to_string()));
        }
        collect_from_dir(default, no_name_check)
    } else {
        let mut out = Vec::new();
        for s in inputs {
            let p = Path::new(s);
            if !p.exists() {
                return Err(MyError::PathNotFound(s.clone()));
            }
            if p.is_file() {
                out.push(p.to_path_buf());
            } else if p.is_dir() {
                let mut v = collect_from_dir(p, no_name_check)?;
                out.append(&mut v);
            } else {
                return Err(MyError::PathNotFound(s.clone()));
            }
        }
        Ok(out)
    }
}

fn collect_from_dir(root: &Path, no_name_check: bool) -> Result<Vec<PathBuf>, MyError> {
    let mut files = Vec::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(dir) = stack.pop() {
        let entries = fs::read_dir(&dir).map_err(|e| MyError::Io(e))?;
        for entry in entries {
            let entry = entry.map_err(|e| MyError::Io(e))?;
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
            } else if path.is_file() {
                if no_name_check {
                    files.push(path);
                } else {
                    if let Some(fname) = path.file_name().and_then(|s| s.to_str()) {
                        if fname.contains("access.log") {
                            files.push(path);
                        }
                    }
                }
            }
        }
    }
    if files.is_empty() {
        Err(MyError::NoLogFileFound)
    } else {
        Ok(files)
    }
}

// ----- Filters -----
#[derive(Debug, Clone)]
enum StrFilterNode {
    Or,
    And,
}
#[derive(Debug, Clone)]
enum StrFilter {
    Regex(Regex),
    Not(Box<StrFilter>),
    And(Box<StrFilter>, Box<StrFilter>),
    Or(Box<StrFilter>, Box<StrFilter>),
}

impl StrFilter {
    fn eval(&self, s: &str) -> bool {
        match self {
            StrFilter::Regex(re) => re.is_match(s),
            StrFilter::Not(inner) => !inner.eval(s),
            StrFilter::And(a,b) => a.eval(s) && b.eval(s),
            StrFilter::Or(a,b) => a.eval(s) || b.eval(s),
        }
    }
}

// Simple parser for path/ip/referer/method filters (boolean expression with regex atoms)
// We implement tokenization that respects spaces around parentheses and operators &,|,!,','
// But also ',' as AND, and whitespace as AND (except around | and ,).
// To match observed behavior:
// - '|' always OR, even without spaces
// - ',' always AND, even without spaces
// - '&' AND only when followed by space (or '('?), but space before optional? Actually observed 'a& b' succeeded, 'a &b' failed.
//   So we will treat '&' as AND only when it is followed by space or '('? But also when preceded by space? Let's attempt:
//   For simplicity, we will parse by splitting on ',' and '|' first? However that loses precedence.
// Let's attempt a more robust approach: tokenize by scanning string, producing tokens:
//   '(' , ')' , '|' , ',' , '&' , '!' , regex atom (sequence of chars not containing those operators unless inside? But regex itself may contain these chars.)
// The doc says add parenthesis around operators to avoid them being understood as part of regex. That suggests that by default operators without spaces may be considered part of regex.
// So to safely parse, we should attempt to find boolean operators that are surrounded by spaces? For '(' and ')' need spaces.
// Let's look at successful patterns that contain parentheses with spaces: 'a | ( b & c )' succeeds, 'a | (b & c)' fails.
// So '(' must be preceded by space (or start?) and followed by space to be recognized as grouping. Similarly ')' must be preceded by space and followed by space or end.
// For '&', must be preceded by space? Actually 'a& b' has no space before but succeeded. So maybe not.
// But 'a &b' failed, so '&' must be followed by space.
// So rule: '&' recognized as AND only if followed by space. Preceded by space optional? But 'a& b' had no space before yet succeeded, so preceding space optional if followed by space.
// Similarly '|' ? 'a|b' succeeded without spaces, so '|' does NOT require spaces.
// ',' ? 'a,b' succeeded without spaces.
// '!' ? For negation, '!a' succeeded (no space). '! a' also succeeded? Let's test: we had '!a' and '! a' both gave 2 lines (b,c). So '!' works with or without space.
// '('? It seems '(' needs space after, but not necessarily before? "(a | b) & c" failed because no space after '(' . "( a | b ) & c" succeeded with space after '(' and before ')'.
// So '(' requires space after.
// ')' requires space before.
//
// Let's attempt to implement tokenization with these rules:

fn tokenize_str_filter(input: &str) -> Result<Vec<String>, StrFilterError> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() || c == ',' {
            // ',' is AND, but also skip whitespace as separator? Actually ',' we treat as AND token, whitespace as separator that implies AND? But we will produce AND token for both ',' and whitespace runs?
            // Simplify: if ',' -> push "AND" token
            // If whitespace, skip but maybe imply AND between atoms? However our parser can treat whitespace as AND as well (by inserting AND tokens between adjacent atoms).
            if c == ',' {
                tokens.push(",".to_string());
            } else {
                // whitespace -> skip, but we need to indicate separation? We'll push a special whitespace token to later convert to AND if needed.
                // Instead, we treat whitespace as delimiter that may imply AND between two regex atoms.
                // We'll push a marker?
            }
            i+=1;
        } else if c == '|' {
            tokens.push("|".to_string());
            i+=1;
        } else if c == '&' {
            // Check if followed by space or '(' or end? For our rule, require space after to be operator, otherwise part of regex.
            // Look ahead
            let next_is_space = if i+1 < chars.len() { chars[i+1].is_whitespace() || chars[i+1]=='(' } else { true }; // at end considered operator?
            if next_is_space {
                tokens.push("&".to_string());
                i+=1;
            } else {
                // part of regex atom, capture until next operator that is recognized
                let start = i;
                // collect until we encounter an operator that should be split
                // For '&' without space after, it's part of atom. So we need to collect atom:
                let mut j = i;
                while j < chars.len() {
                    let cc = chars[j];
                    if cc == '|' || cc == ',' {
                        break;
                    }
                    if cc == '&' {
                        // check if this '&' would be operator (followed by space)
                        let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                        if nxt.is_whitespace() || nxt=='(' {
                            break;
                        }
                    }
                    if cc == '(' || cc == ')' {
                        // Check if '(' would be grouping (needs space after)
                        if cc == '(' {
                            let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                            if nxt.is_whitespace() {
                                break;
                            }
                        } else {
                            let prev = if j>0 { chars[j-1] } else { '\0' };
                            if prev.is_whitespace() {
                                break;
                            }
                        }
                    }
                    if cc == '!' {
                        // '!' at start of token may be operator, but inside regex? We'll treat '!' as operator only if at beginning of atom? For simplicity, break if '!' appears not at start?
                        // Actually '!a' should be Not. So '!' at start is operator.
                        // If we are at start of atom (i==start), and cc=='!', that's operator token, not part of atom. But we are inside else where we treat '&' as part of atom; we shouldn't get here for '!'.
                        // We'll handle '!' outside.
                    }
                    j+=1;
                }
                let atom: String = chars[start..j].iter().collect();
                if !atom.trim().is_empty() {
                    tokens.push(atom.trim().to_string());
                }
                i=j;
            }
        } else if c == '!' {
            tokens.push("!".to_string());
            i+=1;
        } else if c == '(' {
            // check if followed by space -> grouping
            let next_is_space = if i+1 < chars.len() { chars[i+1].is_whitespace() } else { false };
            if next_is_space {
                tokens.push("(".to_string());
                i+=1;
            } else {
                // part of atom
                let start = i;
                let mut j = i;
                while j < chars.len() {
                    let cc = chars[j];
                    if cc == '|' || cc == ',' {
                        break;
                    }
                    if cc == '&' {
                        let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                        if nxt.is_whitespace() || nxt=='(' {
                            break;
                        }
                    }
                    if cc == '(' {
                        let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                        if nxt.is_whitespace() && j!=start {
                            break;
                        }
                    }
                    if cc == ')' {
                        let prev = if j>0 { chars[j-1] } else { '\0' };
                        if prev.is_whitespace() {
                            break;
                        }
                    }
                    // '!' inside? break if at start? Actually we handle '!' outside.
                    if cc.is_whitespace() {
                        break;
                    }
                    j+=1;
                }
                let atom: String = chars[start..j].iter().collect();
                tokens.push(atom.trim().to_string());
                i=j;
            }
        } else if c == ')' {
            let prev_is_space = if i>0 { chars[i-1].is_whitespace() } else { false };
            if prev_is_space {
                tokens.push(")".to_string());
                i+=1;
            } else {
                // part of atom
                let start = i;
                let mut j = i;
                while j < chars.len() {
                    let cc = chars[j];
                    if cc == '|' || cc == ',' {
                        break;
                    }
                    if cc == '&' {
                        let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                        if nxt.is_whitespace() || nxt=='(' {
                            break;
                        }
                    }
                    if cc == '(' {
                        let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                        if nxt.is_whitespace() {
                            break;
                        }
                    }
                    // ')' without preceding space considered part of atom, so continue...
                    if cc.is_whitespace() {
                        break;
                    }
                    j+=1;
                }
                let atom: String = chars[start..j].iter().collect();
                tokens.push(atom.trim().to_string());
                i=j;
            }
        } else {
            // regex atom: collect until operator delimiters
            let start = i;
            let mut j = i;
            while j < chars.len() {
                let cc = chars[j];
                if cc.is_whitespace() || cc == ',' || cc == '|' {
                    break;
                }
                if cc == '&' {
                    let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                    if nxt.is_whitespace() || nxt=='(' {
                        break;
                    }
                }
                if cc == '(' {
                    let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                    if nxt.is_whitespace() {
                        break;
                    }
                }
                if cc == ')' {
                    let prev = if j>0 { chars[j-1] } else { '\0' };
                    if prev.is_whitespace() {
                        break;
                    }
                }
                if cc == '!' {
                    // '!' inside atom? Could be like "!exe" atom? Actually "!" is negation operator, but when combined like "!exe", the token should be "!" + "exe"? Our earlier token for "!exe" would be "!" and "exe" separate? But we pushed "!" token for '!' char, so "!exe" would be two tokens "!" and "exe". That's what we want.
                    // So if we encounter '!' not at start of atom, break?
                    if j!=start {
                        break;
                    }
                }
                j+=1;
            }
            let atom: String = chars[start..j].iter().collect();
            tokens.push(atom.trim().to_string());
            i=j;
        }
    }
    // Now we have tokens like "a", "|", "b", "&", "c", "(", etc, plus commas.
    // But we also need to insert implicit AND between consecutive atoms or atom and '(' or ')' and atom etc that were separated by whitespace or comma.
    // In original, whitespace implies AND. Comma also implies AND.
    // So between two atoms that are adjacent in original string separated only by whitespace, they were intended as AND. Our tokenization skipped whitespace, so we lost that.
    // To replicate, we can insert AND token "AND" between any two tokens where neither is an explicit operator and they were separated by whitespace in original? Complicated.
    // Simpler: we can attempt to produce token list where "," and "&" are AND, "|" is OR, and also we insert AND between adjacent atoms that are not separated by explicit OR.
    // For example, tokens ["a","b"] should become ["a","AND","b"] (since space)
    // tokens ["a",",","b"] -> ["a","AND","b"]
    // tokens ["a","&","b"] -> AND
    // tokens ["a","|","b"] -> OR
    //
    // Let's insert implicit AND:
    let mut final_tokens = Vec::new();
    let mut prev_is_atom_or_rparen = false;
    for tok in tokens {
        let is_atom = tok != "|" && tok != "&" && tok != "," && tok != "!" && tok != "(" && tok != ")";
        let is_rparen = tok == ")";
        let is_lparen = tok == "(";
        let is_not = tok == "!";
        let is_or = tok == "|";
        let is_and = tok == "&" || tok == ",";
        if prev_is_atom_or_rparen && (is_atom || is_lparen || is_not) {
            // implicit AND
            final_tokens.push("&".to_string());
        }
        if is_and {
            final_tokens.push("&".to_string());
        } else if is_or {
            final_tokens.push("|".to_string());
        } else {
            final_tokens.push(tok);
        }
        prev_is_atom_or_rparen = is_atom || is_rparen;
    }
    Ok(final_tokens)
}

// Now parser for expression with precedence? Let's attempt to parse boolean expression with operators ! (not, unary), & (and), | (or), parentheses.
// We'll attempt to implement shunting-yard.

fn parse_tokens_to_filter(tokens: &[String], original_input: &str) -> Result<StrFilter, StrFilterError> {
    // Build AST using shunting yard
    let mut output: Vec<StrFilter> = Vec::new();
    let mut ops: Vec<String> = Vec::new();

    fn precedence(op: &str) -> u8 {
        match op {
            "!" => 3,
            "&" => 2,
            "|" => 1,
            _ => 0,
        }
    }
    fn is_right_assoc(op: &str) -> bool {
        op == "!"
    }

    fn apply_op(op: &str, output: &mut Vec<StrFilter>) -> Result<(), StrFilterError> {
        if op == "!" {
            let a = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing operand".to_string()))?;
            output.push(StrFilter::Not(Box::new(a)));
        } else if op == "&" {
            let b = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing operand".to_string()))?;
            let a = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing operand".to_string()))?;
            output.push(StrFilter::And(Box::new(a), Box::new(b)));
        } else if op == "|" {
            let b = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing operand".to_string()))?;
            let a = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing operand".to_string()))?;
            output.push(StrFilter::Or(Box::new(a), Box::new(b)));
        } else {
            return Err(StrFilterError::InvalidPattern("".to_string(), format!("unknown op {}", op)));
        }
        Ok(())
    }

    for tok in tokens {
        match tok.as_str() {
            "!" => {
                ops.push(tok.clone());
            }
            "&" | "|" => {
                while let Some(top) = ops.last() {
                    if top == "(" {
                        break;
                    }
                    let p_top = precedence(top);
                    let p_cur = precedence(tok);
                    if p_top > p_cur || (p_top == p_cur && !is_right_assoc(tok)) {
                        let op = ops.pop().unwrap();
                        if let Err(_) = apply_op(&op, &mut output) {
                            // convert to InvalidPattern?
                            return Err(StrFilterError::InvalidPattern(original_input.to_string(), "invalid expression".to_string()));
                        }
                    } else {
                        break;
                    }
                }
                ops.push(tok.clone());
            }
            "(" => {
                ops.push(tok.clone());
            }
            ")" => {
                let mut found = false;
                while let Some(op) = ops.pop() {
                    if op == "(" {
                        found = true;
                        break;
                    } else {
                        apply_op(&op, &mut output).map_err(|_| StrFilterError::InvalidPattern(original_input.to_string(), "unexpected closing parenthesis".to_string()))?;
                    }
                }
                if !found {
                    return Err(StrFilterError::InvalidPattern(original_input.to_string(), "unexpected closing parenthesis".to_string()));
                }
            }
            atom => {
                // atom is regex pattern
                // compile regex
                match Regex::new(atom) {
                    Ok(re) => output.push(StrFilter::Regex(re)),
                    Err(e) => return Err(StrFilterError::InvalidRegex(e)),
                }
            }
        }
    }
    while let Some(op) = ops.pop() {
        if op == "(" || op == ")" {
            return Err(StrFilterError::InvalidPattern(original_input.to_string(), "unmatched parenthesis".to_string()));
        }
        apply_op(&op, &mut output).map_err(|_| StrFilterError::InvalidPattern(original_input.to_string(), "invalid expression".to_string()))?;
    }
    if output.len() != 1 {
        return Err(StrFilterError::InvalidPattern(original_input.to_string(), "invalid expression".to_string()));
    }
    Ok(output.pop().unwrap())
}

fn compile_str_filter(pattern: &str) -> Result<StrFilter, MyError> {
    if pattern.is_empty() {
        return Err(MyError::StrFilter(StrFilterError::InvalidRegex(Regex::new("[").unwrap_err())));
    }
    let tokens = tokenize_str_filter(pattern).map_err(|e| MyError::StrFilter(e))?;
    // For debugging, check if any token is empty?
    parse_tokens_to_filter(&tokens, pattern).map_err(|e| MyError::StrFilter(e))
}

