fn format_number(n: usize) -> String {
    // Format with comma thousand separator
    let s = n.to_string();
    let mut result = String::new();
    let mut count = 0;
    for c in s.chars().rev() {
        if count>0 && count%3==0 {
            result.push(',');
        }
        result.push(c);
        count+=1;
    }
    result.chars().rev().collect()
}

