        _ => 120,
    };
    if items.is_empty() {
        println!("0 referrers. ");
        println!("┌───┬────────┬────┬───┬─────┐");
        println!("│ # │referrer│hits│ % │bytes│");
        println!("├───┼────────┼────┼───┼─────┤");
        println!("└───┴────────┴────┴───┴─────┘");
        return;
    }
    println!("{} referrers. {} most frequent:", items.len(), std::cmp::min(limit, items.len()));
    println!("┌───┬────────────────────┬────┬─────┬─────┐");
    println!("│ # │referrer            │hits│  %  │bytes│");
    println!("├───┼────────────────────┼────┼─────┼─────┤");
    let displayed = if items.len() > limit { &items[..limit] } else { &items[..] };
    for (idx, (r, hits, bytes)) in displayed.iter().enumerate() {
        let pct = *hits as f64 / total_hits as f64 * 100.0;
        // truncate referrer to maybe 20 chars?
        let r_display = if r.len()>20 { &r[..20] } else { r };
        println!("│{:>3}│{:<20}│{:>4}│{:>4.1}%│{:>5}│", idx+1, r_display, format_number(*hits), pct, format_bytes(*bytes));
    }
    println!("└───┴────────────────────┴────┴─────┴─────┘");
}

fn print_path_table(entries: &[LogEntry], cli: &Cli, length_level: usize) {
    let mut map: HashMap<String, (usize,u64)> = HashMap::new();
    for e in entries {
        // resource filtering
        if !cli.all {
            if is_resource(&e.path) {
                continue;
            }
        }
        let entry = map.entry(e.path.clone()).or_insert((0,0));
        entry.0+=1;
        entry.1+=e.bytes;
    }
    let total_hits = entries.len();
    let mut items: Vec<(String, usize, u64)> = map.into_iter().map(|(p,(h,b))| (p,h,b)).collect();
    items.sort_by(|a,b| {
        match cli.key {
            Key::Hits => b.1.cmp(&a.1),
            Key::Bytes => b.2.cmp(&a.2),
        }
    });
    let limit = match length_level {
        0 => 10,
        1 => 50,
        2 => 100,
        3 => 150,
        4 => 200,
        5 => 250,
        6 => 300,
        _ => 300,
    };
    let total_paths = items.len();
    if total_paths == 0 {
        println!("0 paths (excluding resources like images, css, etc.). ");
        println!("┌───┬────┬────┬───┬─────┐");
        println!("│ # │path│hits│ % │bytes│");
        println!("├───┼────┼────┼───┼─────┤");
        println!("└───┴────┴────┴───┴─────┘");
        return;
    }
    if cli.all {
        println!("{} paths. ", total_paths);
    } else {
        println!("{} paths (excluding resources like images, css, etc.). ", total_paths);
    }
    println!("┌───┬───────────┬────┬─────┬─────┐");
    println!("│ # │path       │hits│  %  │bytes│");
    println!("├───┼───────────┼────┼─────┼─────┤");
    let displayed = if items.len() > limit { &items[..limit] } else { &items[..] };
    for (idx, (p, hits, bytes)) in displayed.iter().enumerate() {
        let pct = *hits as f64 / total_hits as f64 * 100.0;
        let p_display = if p.len()>11 { &p[..11] } else { p };
        println!("│{:>3}│{:<11}│{:>4}│{:>4.1}%│{:>5}│", idx+1, p_display, format_number(*hits), pct, format_bytes(*bytes));
    }
    println!("└───┴───────────┴────┴─────┴─────┘");
}

fn is_resource(path: &str) -> bool {
    // Check extension: strip query '?'
    let base = path.split('?').next().unwrap_or(path);
    // Get extension after last '.'
    if let Some(dot) = base.rfind('.') {
        let ext = &base[dot+1..];
        // case sensitive lower case only?
        match ext {
            "png" | "jpg" | "jpeg" | "gif" | "ico" | "css" | "js" | "svg" | "woff2" | "webp" => true,
            _ => false,
        }
    } else {
        false
    }
}

