const VERSION: &str = "2.0.4";

#[derive(Debug, Clone, Copy, PartialEq)]
enum ColorChoice { Auto, Yes, No }

impl std::str::FromStr for ColorChoice {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "auto" => Ok(ColorChoice::Auto),
            "yes" => Ok(ColorChoice::Yes),
            "no" => Ok(ColorChoice::No),
            _ => Err(format!("unknown color")),
        }
    }
}
impl std::fmt::Display for ColorChoice {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ColorChoice::Auto=>write!(f,"auto"),
            ColorChoice::Yes=>write!(f,"yes"),
            ColorChoice::No=>write!(f,"no"),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Key { Hits, Bytes }

impl std::str::FromStr for Key {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_ascii_lowercase().as_str() {
            "hits" | "h" => Ok(Key::Hits),
            "bytes" | "b" => Ok(Key::Bytes),
            _ => Err(format!("unrecognized key \"{}\"", s)),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Output { Tables, Raw, Csv, Json }

impl std::str::FromStr for Output {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_ascii_lowercase().as_str() {
            "tables" | "t" => Ok(Output::Tables),
            "raw" | "r" => Ok(Output::Raw),
            "csv" | "c" => Ok(Output::Csv),
            "json" | "j" => Ok(Output::Json),
            _ => Err(format!("unrecognized output \"{}\"", s)),
        }
    }
}

#[derive(Parser, Debug)]
#[command(name = "rhit", version = VERSION, about = "Rhit analyzes your nginx logs.", disable_help_flag = true, disable_version_flag = true)]
