                    // handle wrap-around? If start <= end, simple inclusive, else (e.g., 12/24-01/10) would mean Dec 24 to Jan 10 crossing year? Could be inclusive via OR? Not sure.
                    if start_md <= end_md {
                        md >= start_md && md <= end_md
                    } else {
                        md >= start_md || md <= end_md
                    }
                })
            } else {
                // mixed: one year, one not -> treat yearless as same year as the yearful? Or error?
                // Let's attempt: if left has year, right yearless, use left year for right? Or use any year? For simplicity, if left has year, use that year for right's month/day to define end date.
                // Similarly if right has year, use that year for left.
                if let Some(y1) = y1_opt {
                    // right yearless
                    let start = NaiveDate::from_ymd_opt(y1, m1, d1).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("0".parse::<i32>().unwrap_err())))?;
                    let end = NaiveDate::from_ymd_opt(y1, m2, d2).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("0".parse::<i32>().unwrap_err())))?;
                    Box::new(move |e: &LogEntry| e.date >= start && e.date <= end)
                } else {
                    let y2 = y2_opt.unwrap();
                    let start = NaiveDate::from_ymd_opt(y2, m1, d1).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("0".parse::<i32>().unwrap_err())))?;
                    let end = NaiveDate::from_ymd_opt(y2, m2, d2).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("0".parse::<i32>().unwrap_err())))?;
                    Box::new(move |e: &LogEntry| e.date >= start && e.date <= end)
                }
            };
            Ok(f)
        } else {
            Err(MyError::DateTime(DateTimeError::IntExpected("0".parse::<i32>().unwrap_err())))
        }
    } else {
        // single date
        let (y_opt, m, d) = parse_single_date(s)?;
        let f: Box<dyn Fn(&LogEntry)->bool> = if let Some(y) = y_opt {
            let target = NaiveDate::from_ymd_opt(y, m, d).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("0".parse::<i32>().unwrap_err())))?;
            Box::new(move |e: &LogEntry| e.date == target)
        } else {
            Box::new(move |e: &LogEntry| e.date.month() == m && e.date.day() == d)
        };
        Ok(f)
    }
}

fn parse_time_filter(s: &str) -> Result<Box<dyn Fn(&LogEntry)->bool>, MyError> {
    let s = s.trim();
    if s.is_empty() {
        return Err(MyError::TimeFilter(TimeFilterError::InvalidFormat));
    }
    // Helper to parse HH:MM or HH:MM:SS ?
    fn parse_hms(part: &str) -> Result<u32, MyError> {
        // Expected HH:MM or HH:MM:SS
        let comps: Vec<&str> = part.split(':').collect();
        if comps.len() == 2 {
            let h = comps[0].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            let m = comps[1].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            if h>=24 || m>=60 { return Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)); }
            Ok(h*3600+m*60)
        } else if comps.len() == 3 {
            let h = comps[0].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            let m = comps[1].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            let sec = comps[2].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            if h>=24 || m>=60 || sec>=60 { return Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)); }
            Ok(h*3600+m*60+sec)
        } else {
            Err(MyError::TimeFilter(TimeFilterError::InvalidFormat))
        }
    }

    if s.starts_with('>') {
        let rest = &s[1..].trim();
        let secs = parse_hms(rest)?;
        Ok(Box::new(move |e: &LogEntry| e.time_secs >= secs))
    } else if s.starts_with('<') {
        let rest = &s[1..].trim();
        let secs = parse_hms(rest)?;
        Ok(Box::new(move |e: &LogEntry| e.time_secs <= secs))
    } else if s.contains('-') {
        let parts: Vec<&str> = s.splitn(2, '-').collect();
        if parts.len()!=2 { return Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)); }
        let start = parse_hms(parts[0].trim())?;
        let end = parse_hms(parts[1].trim())?;
        Ok(Box::new(move |e: &LogEntry| {
            let t = e.time_secs;
            if start <= end {
                t >= start && t <= end
            } else {
                t >= start || t <= end
            }
        }))
    } else {
        Err(MyError::TimeFilter(TimeFilterError::InvalidFormat))
    }
}

