fn make_bar(val: f64, max: f64, width: usize) -> String {
    if max <= 0.0 { return " ".repeat(width); }
    let ratio = val / max;
    if ratio <= 0.0 { return " ".repeat(width); }
    let total = ratio * width as f64;
    let full = total.floor() as usize;
    let rem = total - full as f64;
    let mut bar = String::new();
    bar.push_str(&"█".repeat(full));
    if full < width {
        let frac = (rem * 8.0).round() as usize;
        if frac > 0 {
            let ch = match frac {
                1 => "▏",
                2 => "▎",
                3 => "▍",
                4 => "▌",
                5 => "▋",
                6 => "▊",
                7 => "▉",
                8 => "█",
                _ => "",
            };
            bar.push_str(ch);
            // If we added a fractional that is full block, increment full count? Actually if frac==8, it's full, so we already have full+1? We added one char that is full. So we should count it as extra.
            let used = full + 1;
            if used < width {
                bar.push_str(&" ".repeat(width - used));
            }
        } else {
            bar.push_str(&" ".repeat(width - full));
        }
    }
    // Ensure bar length in chars (not bytes) equals width? But with unicode, char count matters. We'll pad spaces to reach width in terms of displayed columns? For simplicity, ensure bar's char count <= width, pad spaces.
    // Count chars
    let char_count = bar.chars().count();
    if char_count < width {
        bar.push_str(&" ".repeat(width - char_count));
    } else if char_count > width {
        bar = bar.chars().take(width).collect();
    }
    bar
}

fn print_time_table(entries: &[LogEntry], cli: &Cli) {
    let mut map: BTreeMap<u32, (usize,u64)> = BTreeMap::new();
    for h in 0..24 {
        map.insert(h, (0,0));
    }
    for e in entries {
        let hour = e.time_secs / 3600;
        let entry = map.get_mut(&hour).unwrap();
        entry.0+=1;
        entry.1+=e.bytes;
    }
    let max_val = match cli.key {
        Key::Hits => map.values().map(|(h,_)| *h as f64).max_by(|a,b| a.partial_cmp(b).unwrap()).unwrap_or(1.0),
        Key::Bytes => map.values().map(|(_,b)| *b as f64).max_by(|a,b| a.partial_cmp(b).unwrap()).unwrap_or(1.0),
    };
    let max_display = match cli.key {
        Key::Hits => format!("{}", max_val as usize),
        Key::Bytes => format_bytes(max_val as u64),
    };
    let hist_width = 20;
    let max_len = max_display.len();
    let hist_header = if max_len >= hist_width {
        max_display.clone()
    } else {
        let spaces = hist_width -1 - max_len;
        format!("0{}{}", " ".repeat(spaces), max_display)
    };
    println!("┌────┬────┬─────┬────────────────────┐");
    println!("│hour│hits│bytes│{}│", hist_header);
    println!("├────┼────┼─────┼────────────────────┤");
    for hour in 0..24 {
        let (hits, bytes) = map.get(&hour).unwrap();
        let hits_fmt = format_number(*hits);
        let bytes_fmt = format_bytes(*bytes);
        let val = match cli.key {
            Key::Hits => *hits as f64,
            Key::Bytes => *bytes as f64,
        };
        let bar = make_bar(val, max_val, hist_width);
        println!("│{:>3} │{:>4}│{:>5}│{}│", hour, hits_fmt, bytes_fmt, bar);
    }
    println!("└────┴────┴─────┴────────────────────┘");
}

