fn is_resource(path: &str) -> bool {
    // Check extension: strip query '?'
    let base = path.split('?').next().unwrap_or(path);
    // Get extension after last '.'
    if let Some(dot) = base.rfind('.') {
        let ext = &base[dot+1..];
        // case sensitive lower case only?
        match ext {
            "png" | "jpg" | "jpeg" | "gif" | "ico" | "css" | "js" | "svg" | "woff2" | "webp" => true,
            _ => false,
        }
    } else {
        false
    }
}

