    println!("└────┴────┴─────┴────────────────────┘");
}

fn print_generic_table<K: std::fmt::Display + Ord + Clone>(title: &str, col_name: &str, items: &[(K, usize, u64)], total_hits: usize, cli: &Cli, limit: usize, show_days: bool) {
