fn print_ref_table(entries: &[LogEntry], cli: &Cli, length_level: usize) {
    let mut map: HashMap<String,(usize,u64)>=HashMap::new();
    for e in entries {
        if e.referer=="-" {continue;}
        let entry=map.entry(e.referer.clone()).or_insert((0,0));
        entry.0+=1;
        entry.1+=e.bytes;
