    let displayed = if total>limit { &items[..limit] } else { &items[..] };
    if show_days {
        // with days and trend – not implemented fully, use simple
        println!("{} paths (excluding resources like images, css, etc.)", total);
        println!("┌───┬───────────┬────┬─────┬─────┐");
        println!("│ # │{}       │hits│  %  │bytes│", col_name);
        println!("├───┼───────────┼────┼─────┼─────┤");
        for (idx,(k,hits,bytes)) in displayed.iter().enumerate() {
            let pct=*hits as f64 / total_hits as f64 *100.0;
            println!("│{:>3}│{:<11}│{:>4}│{:>4.1}%│{:>5}│", idx+1, format!("{}",k), format_number(*hits), pct, format_bytes(*bytes));
        }
        println!("└───┴───────────┴────┴─────┴─────┘");
    } else {
        println!("{} {}. ", total, title);
        println!("┌───┬───────────┬────┬─────┬─────┐");
        println!("│ # │{}       │hits│  %  │bytes│", col_name);
        println!("├───┼───────────┼────┼─────┼─────┤");
        for (idx,(k,hits,bytes)) in displayed.iter().enumerate() {
            let pct=*hits as f64 / total_hits as f64 *100.0;
            println!("│{:>3}│{:<11}│{:>4}│{:>4.1}%│{:>5}│", idx+1, format!("{}",k), format_number(*hits), pct, format_bytes(*bytes));
        }
        println!("└───┴───────────┴────┴─────┴─────┘");
    }
}

fn print_method_table(entries: &[LogEntry], cli: &Cli, length_level: usize) {
    let mut map: HashMap<String,(usize,u64)>=HashMap::new();
    for e in entries {
        let entry=map.entry(e.method.clone()).or_insert((0,0));
        entry.0+=1;
        entry.1+=e.bytes;
    }
    let total=entries.len();
    let mut items: Vec<(String,usize,u64)>=map.into_iter().map(|(k,(h,b))| (k,h,b)).collect();
    items.sort_by(|a,b| match cli.key { Key::Hits=>b.1.cmp(&a.1), Key::Bytes=>b.2.cmp(&a.2) });
    let limit=match length_level {0=>3,1=>5,2=>20,3=>30,4=>40,5=>50,6=>60,_=>60};
