impl StrFilter {
    fn eval(&self, s: &str) -> bool {
        match self {
            StrFilter::Regex(re) => re.is_match(s),
            StrFilter::Not(inner) => !inner.eval(s),
            StrFilter::And(a,b) => a.eval(s) && b.eval(s),
            StrFilter::Or(a,b) => a.eval(s) || b.eval(s),
        }
    }
}

fn tokenize_str_filter(input: &str) -> Result<Vec<String>, StrFilterError> {
    let mut tokens = Vec::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() || c == ',' {
            if c == ',' { tokens.push(",".to_string()); }
            i+=1;
        } else if c == '|' {
            tokens.push("|".to_string());
            i+=1;
        } else if c == '&' {
            let next_is_space = if i+1 < chars.len() { chars[i+1].is_whitespace() || chars[i+1]=='(' } else { true };
            if next_is_space {
                tokens.push("&".to_string());
                i+=1;
            } else {
                let start = i;
                let mut j = i;
                while j < chars.len() {
                    let cc = chars[j];
                    if cc == '|' || cc == ',' { break; }
                    if cc == '&' {
                        let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                        if nxt.is_whitespace() || nxt=='(' { break; }
                    }
                    if cc == '(' {
                        let nxt = if j+1 < chars.len() { chars[j+1] } else { '\0' };
                        if nxt.is_whitespace() { break; }
                    }
                    if cc == ')' {
                        let prev = if j>0 { chars[j-1] } else { '\0' };
                        if prev.is_whitespace() { break; }
                    }
                    if cc.is_whitespace() { break; }
                    j+=1;
                }
                let atom: String = chars[start..j].iter().collect();
                if !atom.trim().is_empty() { tokens.push(atom.trim().to_string()); }
                i=j;
            }
        } else if c == '!' {
            tokens.push("!".to_string());
            i+=1;
        } else if c == '(' {
            let next_is_space = if i+1 < chars.len() { chars[i+1].is_whitespace() } else { false };
            if next_is_space { tokens.push("(".to_string()); i+=1; }
            else {
                let start=i;
                let mut j=i;
                while j<chars.len() {
                    let cc=chars[j];
                    if cc=='|'||cc==',' {break;}
                    if cc=='&' { let nxt= if j+1<chars.len(){chars[j+1]} else {'\0'}; if nxt.is_whitespace()||nxt=='(' {break;} }
                    if cc=='(' { let nxt= if j+1<chars.len(){chars[j+1]} else {'\0'}; if nxt.is_whitespace() && j!=start {break;} }
                    if cc==')' { let prev= if j>0{chars[j-1]} else {'\0'}; if prev.is_whitespace(){break;} }
                    if cc.is_whitespace(){break;}
                    j+=1;
                }
                let atom: String = chars[start..j].iter().collect();
                tokens.push(atom.trim().to_string());
                i=j;
            }
        } else if c == ')' {
            let prev_is_space = if i>0 { chars[i-1].is_whitespace() } else { false };
            if prev_is_space { tokens.push(")".to_string()); i+=1; }
            else {
                let start=i;
                let mut j=i;
                while j<chars.len() {
                    let cc=chars[j];
                    if cc=='|'||cc==',' {break;}
                    if cc=='&' { let nxt= if j+1<chars.len(){chars[j+1]} else {'\0'}; if nxt.is_whitespace()||nxt=='(' {break;} }
                    if cc=='(' { let nxt= if j+1<chars.len(){chars[j+1]} else {'\0'}; if nxt.is_whitespace(){break;} }
                    if cc.is_whitespace(){break;}
                    j+=1;
                }
                let atom: String = chars[start..j].iter().collect();
                tokens.push(atom.trim().to_string());
                i=j;
            }
        } else {
            let start=i;
            let mut j=i;
            while j<chars.len() {
                let cc=chars[j];
                if cc.is_whitespace()||cc==','||cc=='|' {break;}
                if cc=='&' { let nxt= if j+1<chars.len(){chars[j+1]} else {'\0'}; if nxt.is_whitespace()||nxt=='(' {break;} }
                if cc=='(' { let nxt= if j+1<chars.len(){chars[j+1]} else {'\0'}; if nxt.is_whitespace(){break;} }
                if cc==')' { let prev= if j>0{chars[j-1]} else {'\0'}; if prev.is_whitespace(){break;} }
                if cc=='!' && j!=start {break;}
                j+=1;
            }
            let atom: String = chars[start..j].iter().collect();
            tokens.push(atom.trim().to_string());
            i=j;
        }
    }
    let mut final_tokens = Vec::new();
    let mut prev_is_atom_or_rparen = false;
    for tok in tokens {
        let is_atom = tok!="|"&&tok!="&"&&tok!=","&&tok!="!"&&tok!="("&&tok!=")";
        let is_rparen = tok==")";
        let is_lparen = tok=="(";
        let is_not = tok=="!";
        let is_or = tok=="|";
        let is_and = tok=="&"||tok==",";
        if prev_is_atom_or_rparen && (is_atom || is_lparen || is_not) {
            final_tokens.push("&".to_string());
        }
        if is_and { final_tokens.push("&".to_string()); }
        else if is_or { final_tokens.push("|".to_string()); }
        else { final_tokens.push(tok); }
        prev_is_atom_or_rparen = is_atom || is_rparen;
    }
    Ok(final_tokens)
}

fn parse_tokens_to_filter(tokens: &[String], original_input: &str) -> Result<StrFilter, StrFilterError> {
    let mut output: Vec<StrFilter> = Vec::new();
    let mut ops: Vec<String> = Vec::new();
    fn precedence(op: &str) -> u8 { match op { "!"=>3,"&"=>2,"|"=>1,_=>0 } }
    fn is_right_assoc(op: &str) -> bool { op=="!" }
    fn apply_op(op: &str, output: &mut Vec<StrFilter>) -> Result<(), StrFilterError> {
        if op=="!" {
            let a = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing".to_string()))?;
            output.push(StrFilter::Not(Box::new(a)));
        } else if op=="&" {
            let b = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing".to_string()))?;
            let a = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing".to_string()))?;
            output.push(StrFilter::And(Box::new(a), Box::new(b)));
        } else if op=="|" {
            let b = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing".to_string()))?;
            let a = output.pop().ok_or_else(|| StrFilterError::InvalidPattern("".to_string(), "missing".to_string()))?;
            output.push(StrFilter::Or(Box::new(a), Box::new(b)));
        }
        Ok(())
    }
    for tok in tokens {
        match tok.as_str() {
            "!" => ops.push(tok.clone()),
            "&" | "|" => {
                while let Some(top)=ops.last() {
                    if top=="(" {break;}
                    let p_top=precedence(top);
                    let p_cur=precedence(tok);
                    if p_top>p_cur || (p_top==p_cur && !is_right_assoc(tok)) {
                        let op=ops.pop().unwrap();
                        apply_op(&op,&mut output).map_err(|_| StrFilterError::InvalidPattern(original_input.to_string(),"invalid".to_string()))?;
                    } else {break;}
                }
                ops.push(tok.clone());
            },
            "(" => ops.push(tok.clone()),
            ")" => {
                let mut found=false;
                while let Some(op)=ops.pop() {
                    if op=="(" {found=true; break;}
                    else { apply_op(&op,&mut output).map_err(|_| StrFilterError::InvalidPattern(original_input.to_string(),"unexpected closing parenthesis".to_string()))?; }
                }
                if !found { return Err(StrFilterError::InvalidPattern(original_input.to_string(),"unexpected closing parenthesis".to_string())); }
            },
            atom => {
                match Regex::new(atom) {
                    Ok(re)=> output.push(StrFilter::Regex(re)),
                    Err(e)=> return Err(StrFilterError::InvalidRegex(e)),
                }
            }
        }
    }
    while let Some(op)=ops.pop() {
        if op=="("||op==")" { return Err(StrFilterError::InvalidPattern(original_input.to_string(),"unmatched parenthesis".to_string())); }
        apply_op(&op,&mut output).map_err(|_| StrFilterError::InvalidPattern(original_input.to_string(),"invalid".to_string()))?;
    }
    if output.len()!=1 { return Err(StrFilterError::InvalidPattern(original_input.to_string(),"invalid".to_string())); }
    Ok(output.pop().unwrap())
}

fn compile_str_filter(pattern: &str) -> Result<StrFilter, MyError> {
    if pattern.is_empty() {
        let err = Regex::new("[").unwrap_err();
        return Err(MyError::StrFilter(StrFilterError::InvalidRegex(err)));
    }
    let tokens = tokenize_str_filter(pattern).map_err(|e| MyError::StrFilter(e))?;
    parse_tokens_to_filter(&tokens, pattern).map_err(|e| MyError::StrFilter(e))
}

fn parse_date_filter(s: &str) -> Result<Box<dyn Fn(&LogEntry)->bool>, MyError> {
    fn parse_single(part: &str) -> Result<(Option<i32>, u32, u32), MyError> {
        let part=part.trim();
        let comps: Vec<&str> = part.split('/').collect();
        if comps.len()==3 {
            let y = comps[0].parse::<i32>().map_err(|e| MyError::DateTime(DateTimeError::IntExpected(e)))?;
            let m = comps[1].parse::<u32>().map_err(|e| MyError::DateTime(DateTimeError::IntExpected(e)))?;
            let d = comps[2].parse::<u32>().map_err(|e| MyError::DateTime(DateTimeError::IntExpected(e)))?;
            Ok((Some(y),m,d))
        } else if comps.len()==2 {
            let m = comps[0].parse::<u32>().map_err(|e| MyError::DateTime(DateTimeError::IntExpected(e)))?;
            let d = comps[1].parse::<u32>().map_err(|e| MyError::DateTime(DateTimeError::IntExpected(e)))?;
            Ok((None,m,d))
        } else {
            Err(MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))
        }
    }
    let s = s.trim();
    if s.contains('-') {
        let parts: Vec<&str> = s.splitn(2, '-').collect();
        let left=parts[0].trim();
        let right=parts[1].trim();
        if left.is_empty() || right.is_empty() {
            return Err(MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())));
        }
        let (y1,m1,d1)=parse_single(left)?;
        let (y2,m2,d2)=parse_single(right)?;
        let f: Box<dyn Fn(&LogEntry)->bool> = if y1.is_some() && y2.is_some() {
            let start=NaiveDate::from_ymd_opt(y1.unwrap(),m1,d1).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))?;
            let end=NaiveDate::from_ymd_opt(y2.unwrap(),m2,d2).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))?;
            Box::new(move |e: &LogEntry| e.date>=start && e.date<=end)
        } else if y1.is_none() && y2.is_none() {
            let sm=(m1,d1);
            let em=(m2,d2);
            Box::new(move |e: &LogEntry| {
                let md=(e.date.month(), e.date.day());
                if sm<=em { md>=sm && md<=em } else { md>=sm || md<=em }
            })
        } else {
            if let Some(y1v)=y1 {
                let start=NaiveDate::from_ymd_opt(y1v,m1,d1).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))?;
                let end=NaiveDate::from_ymd_opt(y1v,m2,d2).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))?;
                Box::new(move |e: &LogEntry| e.date>=start && e.date<=end)
            } else {
                let y2v=y2.unwrap();
                let start=NaiveDate::from_ymd_opt(y2v,m1,d1).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))?;
                let end=NaiveDate::from_ymd_opt(y2v,m2,d2).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))?;
                Box::new(move |e: &LogEntry| e.date>=start && e.date<=end)
            }
        };
        Ok(f)
    } else {
        let (y_opt,m,d)=parse_single(s)?;
        let f: Box<dyn Fn(&LogEntry)->bool> = if let Some(y)=y_opt {
            let target=NaiveDate::from_ymd_opt(y,m,d).ok_or_else(|| MyError::DateTime(DateTimeError::IntExpected("".parse::<i32>().unwrap_err())))?;
            Box::new(move |e: &LogEntry| e.date==target)
        } else {
            Box::new(move |e: &LogEntry| e.date.month()==m && e.date.day()==d)
        };
        Ok(f)
    }
}

fn parse_time_filter(s: &str) -> Result<Box<dyn Fn(&LogEntry)->bool>, MyError> {
    fn parse_hms(part: &str) -> Result<u32, MyError> {
        let comps: Vec<&str> = part.split(':').collect();
        if comps.len()==2 {
            let h=comps[0].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            let m=comps[1].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            if h>=24||m>=60 { return Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)); }
            Ok(h*3600+m*60)
        } else if comps.len()==3 {
            let h=comps[0].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            let m=comps[1].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            let sec=comps[2].parse::<u32>().map_err(|e| MyError::TimeFilter(TimeFilterError::TimeParse(DateTimeError::IntExpected(e))))?;
            if h>=24||m>=60||sec>=60 { return Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)); }
            Ok(h*3600+m*60+sec)
        } else { Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)) }
    }
    let s=s.trim();
    if s.is_empty() { return Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)); }
    if s.starts_with('>') {
        let rest=s[1..].trim();
        let secs=parse_hms(rest)?;
        Ok(Box::new(move |e: &LogEntry| e.time_secs>=secs))
    } else if s.starts_with('<') {
        let rest=s[1..].trim();
        let secs=parse_hms(rest)?;
        Ok(Box::new(move |e: &LogEntry| e.time_secs<=secs))
    } else if s.contains('-') {
        let parts: Vec<&str>=s.splitn(2,'-').collect();
        let start=parse_hms(parts[0].trim())?;
        let end=parse_hms(parts[1].trim())?;
        Ok(Box::new(move |e: &LogEntry| {
            let t=e.time_secs;
            if start<=end { t>=start && t<=end } else { t>=start || t<=end }
        }))
    } else { Err(MyError::TimeFilter(TimeFilterError::InvalidFormat)) }
}

fn parse_status_filter(s: &str) -> Result<Box<dyn Fn(&LogEntry)->bool>, MyError> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).filter(|p| !p.is_empty()).collect();
    if parts.is_empty() { return Err(MyError::StatusFilter(StatusFilterError::ParseInt("".parse::<u16>().unwrap_err()))); }
    struct Rule { neg: bool, check: Box<dyn Fn(u16)->bool> }
    let mut rules: Vec<Rule> = Vec::new();
    for part in parts {
        let (neg, pat) = if part.starts_with('!') { (true, part[1..].trim()) } else { (false, part) };
        if pat.is_empty() { return Err(MyError::StatusFilter(StatusFilterError::ParseInt("".parse::<u16>().unwrap_err()))); }
        let check: Box<dyn Fn(u16)->bool> = if pat.to_ascii_lowercase().contains('x') {
            let lower=pat.to_ascii_lowercase().replace('x',"0");
            let upper=pat.to_ascii_lowercase().replace('x',"9");
            let l=lower.parse::<u16>().map_err(|e| MyError::StatusFilter(StatusFilterError::ParseInt(e)))?;
            let u=upper.parse::<u16>().map_err(|e| MyError::StatusFilter(StatusFilterError::ParseInt(e)))?;
            Box::new(move |code| code>=l && code<=u)
        } else if pat.contains('-') {
            let rp: Vec<&str>=pat.splitn(2,'-').collect();
            let start=rp[0].trim().parse::<u16>().map_err(|e| MyError::StatusFilter(StatusFilterError::ParseInt(e)))?;
            let end=rp[1].trim().parse::<u16>().map_err(|e| MyError::StatusFilter(StatusFilterError::ParseInt(e)))?;
            Box::new(move |code| code>=start && code<=end)
        } else {
            let code=pat.parse::<u16>().map_err(|e| MyError::StatusFilter(StatusFilterError::ParseInt(e)))?;
            Box::new(move |c| c==code)
        };
        rules.push(Rule{neg, check});
    }
    let mut pos: Vec<Box<dyn Fn(u16)->bool>> = Vec::new();
    let mut neg: Vec<Box<dyn Fn(u16)->bool>> = Vec::new();
    for r in rules { if r.neg { neg.push(r.check); } else { pos.push(r.check); } }
    Ok(Box::new(move |e: &LogEntry| {
        let code=e.status;
        if !pos.is_empty() {
            let mut matched=false;
            for p in &pos { if p(code) { matched=true; break; } }
            if !matched { return false; }
        }
        for n in &neg { if n(code) { return false; } }
        true
    }))
}

fn parse_method_filter(s: &str) -> Result<Box<dyn Fn(&LogEntry)->bool>, MyError> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).filter(|p| !p.is_empty()).collect();
    if parts.is_empty() { return Err(MyError::StatusFilter(StatusFilterError::ParseInt("".parse::<u16>().unwrap_err()))); }
    let mut rules: Vec<(bool,String)> = Vec::new();
    for p in parts {
        let (neg,val)= if p.starts_with('!') {(true,p[1..].trim().to_string())} else {(false,p.trim().to_string())};
        rules.push((neg,val));
    }
    Ok(Box::new(move |e: &LogEntry| {
        for (neg,val) in &rules {
            let matches = e.method==*val;
            if *neg { if matches { return false; } } else { if !matches { return false; } }
        }
        true
    }))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
enum Field { Date, Time, Method, Status, Ip, Ref, Path }

fn parse_fields_input(s: &str) -> Result<Vec<Field>, MyError> {
    let default_fields = vec![Field::Date, Field::Status, Field::Ref, Field::Path];
    let all_fields = vec![Field::Date, Field::Time, Field::Method, Field::Status, Field::Ip, Field::Ref, Field::Path];
    let mut tokens: Vec<(char,String)> = Vec::new();
    let mut cur_sign='\0';
    let mut cur_name=String::new();
    let chars: Vec<char>=s.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c=chars[i];
        if c==',' {
            if !cur_name.is_empty() { tokens.push((cur_sign, cur_name.clone())); cur_name.clear(); cur_sign='\0'; }
            i+=1;
        } else if c=='+'||c=='-' {
            if !cur_name.is_empty() { tokens.push((cur_sign, cur_name.clone())); cur_name.clear(); }
            cur_sign=c;
            i+=1;
        } else { cur_name.push(c); i+=1; }
    }
    if !cur_name.is_empty() { tokens.push((cur_sign, cur_name)); }
    let mut result: Vec<Field>=Vec::new();
    let first_sign = if !tokens.is_empty() { tokens[0].0 } else { '\0' };
    if first_sign=='+'||first_sign=='-' { result=default_fields.clone(); }
    for (sign,name) in tokens {
        let trim=name.trim();
        if trim.is_empty() {continue;}
        let lower=trim.to_ascii_lowercase();
        if lower.starts_with('a') {
            if sign=='-' { result.clear(); }
            else {
                if result.is_empty() { result=all_fields.clone(); }
                else {
                    for f in &all_fields {
                        if result.contains(f) { result.retain(|x| x!=f); }
                        result.push(*f);
                    }
                }
            }
        } else {
            let c = lower.chars().next().unwrap();
            let field_opt = match c {
                'd'=>Some(Field::Date),
                't'=>Some(Field::Time),
                'm'=>Some(Field::Method),
                's'=>Some(Field::Status),
                'i'=>Some(Field::Ip),
                'r'=>Some(Field::Ref),
                'p'=>Some(Field::Path),
                _=>None,
            };
            if let Some(f)=field_opt {
                if sign=='-' { result.retain(|x| x!=&f); }
                else {
                    if result.contains(&f) { result.retain(|x| x!=&f); }
                    result.push(f);
                }
            } else {
                eprintln!("error: invalid value '{}' for '--fields <FIELDS>': unrecognized field start '{}'", s, c);
                std::process::exit(2);
            }
        }
    }
    Ok(result)
}

fn format_number(n: usize) -> String {
    let s=n.to_string();
    let mut res=String::new();
    let mut cnt=0;
    for ch in s.chars().rev() {
        if cnt>0 && cnt%3==0 { res.push(','); }
        res.push(ch);
        cnt+=1;
    }
    res.chars().rev().collect()
}

fn make_bar(val: f64, max: f64, width: usize) -> String {
    if max<=0.0 { return " ".repeat(width); }
    let ratio=val/max;
    if ratio<=0.0 { return " ".repeat(width); }
    let total=ratio*width as f64;
    let full=total.floor() as usize;
    let rem=total-full as f64;
    let mut bar=String::new();
    bar.push_str(&"█".repeat(full));
    if full<width {
        let frac=(rem*8.0).round() as usize;
        if frac>0 {
            let ch=match frac {1=>"▏",2=>"▎",3=>"▍",4=>"▌",5=>"▋",6=>"▊",7=>"▉",8=>"█",_=>""};
            bar.push_str(ch);
            let used=full+1;
            if used<width { bar.push_str(&" ".repeat(width-used)); }
        } else { bar.push_str(&" ".repeat(width-full)); }
    }
    let cnt=bar.chars().count();
    if cnt<width { bar.push_str(&" ".repeat(width-cnt)); }
    else if cnt>width { bar=bar.chars().take(width).collect(); }
    bar
}

fn print_date_table(ordered: &[NaiveDate], map: &BTreeMap<NaiveDate, (usize,u64)>, cli: &SimpleCli) {
    let max_val = match cli.key {
        Key::Hits => map.values().map(|(h,_)| *h as f64).fold(0.0,f64::max),
        Key::Bytes => map.values().map(|(_,b)| *b as f64).fold(0.0,f64::max),
    };
    let max_display = match cli.key {
        Key::Hits => format!("{}", max_val as usize),
        Key::Bytes => format_bytes(max_val as u64),
    };
    let hist_width=20;
    let max_len=max_display.len();
    let hist_header = if max_len>=hist_width { max_display.clone() } else { let spaces=hist_width-1-max_len; format!("0{}{}", " ".repeat(spaces), max_display) };
    println!("┌──────────┬────┬─────┬────────────────────┐");
    println!("│   date   │hits│bytes│{}│", hist_header);
    println!("├──────────┼────┼─────┼────────────────────┤");
    for date in ordered {
        let (hits,bytes)=map.get(date).unwrap();
        let date_str=date.format("%Y/%m/%d").to_string();
        let bar=make_bar(match cli.key { Key::Hits=>*hits as f64, Key::Bytes=>*bytes as f64 }, max_val, hist_width);
        println!("│{}│{:>4}│{:>5}│{}│", date_str, format_number(*hits), format_bytes(*bytes), bar);
    }
    println!("└──────────┴────┴─────┴────────────────────┘");
}

fn print_time_table(entries: &[LogEntry], cli: &SimpleCli) {
