}

fn print_path_table(entries: &[LogEntry], cli: &SimpleCli, length_level: usize) {
    let mut map: HashMap<String,(usize,u64)>=HashMap::new();
    for e in entries {
        if !cli.all && is_resource(&e.path) {continue;}
        let entry=map.entry(e.path.clone()).or_insert((0,0));
        entry.0+=1;
        entry.1+=e.bytes;
    }
    let total=entries.len();
    let mut items: Vec<(String,usize,u64)>=map.into_iter().collect();
    items.sort_by(|a,b| match cli.key { Key::Hits=>b.1.cmp(&a.1), Key::Bytes=>b.2.cmp(&a.2) });
    let limit=match length_level {0=>10,1=>50,2=>100,3=>150,4=>200,5=>250,6=>300,_=>300};
    if items.is_empty() {
        if cli.all {
            println!("0 paths. ");
            println!("┌───┬────┬────┬───┬─────┐");
            println!("│ # │path│hits│ % │bytes│");
            println!("├───┼────┼────┼───┼─────┤");
            println!("└───┴────┴────┴───┴─────┘");
        } else {
            println!("0 paths (excluding resources like images, css, etc.). ");
            println!("┌───┬────┬────┬───┬─────┐");
            println!("│ # │path│hits│ % │bytes│");
            println!("├───┼────┼────┼───┼─────┤");
            println!("└───┴────┴────┴───┴─────┘");
        }
        return;
    }
    if cli.all { println!("{} paths. ", items.len()); } else { println!("{} paths (excluding resources like images, css, etc.). ", items.len()); }
    println!("┌───┬───────────┬────┬─────┬─────┐");
    println!("│ # │path       │hits│  %  │bytes│");
    println!("├───┼───────────┼────┼─────┼─────┤");
    let disp=if items.len()>limit {&items[..limit]} else {&items[..]};
    for (idx,(p,hits,bytes)) in disp.iter().enumerate() {
        let pct=*hits as f64 / total as f64 *100.0;
        let pd=if p.len()>11 {&p[..11]} else {p};
        println!("│{:>3}│{:<11}│{:>4}│{:>4.1}%│{:>5}│", idx+1, pd, format_number(*hits), pct, format_bytes(*bytes));
    }
    println!("└───┴───────────┴────┴─────┴─────┘");
}

fn is_resource(path: &str) -> bool {
    let base = path.split('?').next().unwrap_or(path);
    if let Some(dot)=base.rfind('.') {
        let ext=&base[dot+1..];
        matches!(ext, "png"|"jpg"|"jpeg"|"gif"|"ico"|"css"|"js"|"svg"|"woff2"|"webp")
    } else { false }
}

