#[derive(Debug)]
struct SimpleCli {
    files: Vec<String>,
    color: ColorChoice,
    key: Key,
    length: String,
    fields: String,
    changes: bool,
    date: Option<String>,
    ip: Option<String>,
    method: Option<String>,
    path: Option<String>,
    referer: Option<String>,
    status: Option<String>,
    time: Option<String>,
    all: bool,
    no_name_check: bool,
    output: Output,
    silent_load: bool,
}

fn parse_cli() -> Result<SimpleCli, String> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.iter().any(|a| a=="--help") {
        generate_and_print_help();
        std::process::exit(0);
    }
    if args.iter().any(|a| a=="--version") {
        println!("rhit {}", VERSION);
        std::process::exit(0);
    }
    let mut cli = SimpleCli {
        files: Vec::new(),
        color: ColorChoice::Auto,
        key: Key::Hits,
        length: "1".to_string(),
        fields: "date,status,ref,path".to_string(),
        changes: false,
        date: None,
        ip: None,
        method: None,
        path: None,
        referer: None,
        status: None,
        time: None,
        all: false,
        no_name_check: false,
        output: Output::Tables,
        silent_load: false,
    };
    let mut i=0;
    while i<args.len() {
        let a = args[i].clone();
        if a=="--help" { generate_and_print_help(); std::process::exit(0); }
        else if a=="--version" { println!("rhit {}", VERSION); std::process::exit(0); }
        else if a=="--color" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--color <COLOR>' but none was supplied"); std::process::exit(2); }
            cli.color=args[i].parse::<ColorChoice>().unwrap_or_else(|_| { eprintln!("error: invalid value '{}' for '--color <COLOR>': unknown", args[i]); std::process::exit(2); });
        } else if a.starts_with("--color=") {
            let v=a.splitn(2,'=').nth(1).unwrap();
            cli.color=v.parse::<ColorChoice>().unwrap_or_else(|_| { eprintln!("error: invalid value '{}' for '--color <COLOR>': unknown", v); std::process::exit(2); });
        } else if a=="-k" || a=="--key" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--key <KEY>' but none was supplied"); std::process::exit(2); }
            let v=&args[i];
            match v.parse::<Key>() {
                Ok(k)=>cli.key=k,
                Err(e)=>{ eprintln!("error: invalid value '{}' for '--key <KEY>': {}", v, e); std::process::exit(2); }
            }
        } else if a.starts_with("--key=") {
            let v=a.splitn(2,'=').nth(1).unwrap();
            match v.parse::<Key>() {
                Ok(k)=>cli.key=k,
                Err(e)=>{ eprintln!("error: invalid value '{}' for '--key <KEY>': {}", v, e); std::process::exit(2); }
            }
        } else if a.starts_with("-k") && a.len()>2 {
            let v=&a[2..];
            match v.parse::<Key>() {
                Ok(k)=>cli.key=k,
                Err(e)=>{ eprintln!("error: invalid value '{}' for '--key <KEY>': {}", v, e); std::process::exit(2); }
            }
        } else if a=="-l" || a=="--length" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--length <LENGTH>' but none was supplied"); std::process::exit(2); }
            cli.length=args[i].clone();
        } else if a.starts_with("--length=") { cli.length=a.splitn(2,'=').nth(1).unwrap().to_string(); }
        else if a.starts_with("-l") && a.len()>2 { cli.length=a[2..].to_string(); }
        else if a=="-f" || a=="--fields" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--fields <FIELDS>' but none was supplied"); std::process::exit(2); }
            cli.fields=args[i].clone();
        } else if a.starts_with("--fields=") { cli.fields=a.splitn(2,'=').nth(1).unwrap().to_string(); }
        else if a.starts_with("-f") && a.len()>2 { cli.fields=a[2..].to_string(); }
        else if a=="-c" || a=="--changes" { cli.changes=true; }
        else if a=="-d" || a=="--date" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--date <DATE>' but none was supplied"); std::process::exit(2); }
            cli.date=Some(args[i].clone());
        } else if a.starts_with("--date=") { cli.date=Some(a.splitn(2,'=').nth(1).unwrap().to_string()); }
        else if a.starts_with("-d") && a.len()>2 { cli.date=Some(a[2..].to_string()); }
        else if a=="-i" || a=="--ip" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--ip <IP>' but none was supplied"); std::process::exit(2); }
            cli.ip=Some(args[i].clone());
        } else if a.starts_with("--ip=") { cli.ip=Some(a.splitn(2,'=').nth(1).unwrap().to_string()); }
        else if a.starts_with("-i") && a.len()>2 { cli.ip=Some(a[2..].to_string()); }
        else if a=="-m" || a=="--method" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--method <METHOD>' but none was supplied"); std::process::exit(2); }
            cli.method=Some(args[i].clone());
        } else if a.starts_with("--method=") { cli.method=Some(a.splitn(2,'=').nth(1).unwrap().to_string()); }
        else if a.starts_with("-m") && a.len()>2 { cli.method=Some(a[2..].to_string()); }
        else if a=="-p" || a=="--path" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--path <PATH>' but none was supplied"); std::process::exit(2); }
            cli.path=Some(args[i].clone());
        } else if a.starts_with("--path=") { cli.path=Some(a.splitn(2,'=').nth(1).unwrap().to_string()); }
        else if a.starts_with("-p") && a.len()>2 { cli.path=Some(a[2..].to_string()); }
        else if a=="-r" || a=="--referer" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--referer <REFERER>' but none was supplied"); std::process::exit(2); }
            cli.referer=Some(args[i].clone());
        } else if a.starts_with("--referer=") { cli.referer=Some(a.splitn(2,'=').nth(1).unwrap().to_string()); }
        else if a.starts_with("-r") && a.len()>2 { cli.referer=Some(a[2..].to_string()); }
        else if a=="-s" || a=="--status" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--status <STATUS>' but none was supplied"); std::process::exit(2); }
            cli.status=Some(args[i].clone());
        } else if a.starts_with("--status=") { cli.status=Some(a.splitn(2,'=').nth(1).unwrap().to_string()); }
        else if a.starts_with("-s") && a.len()>2 { cli.status=Some(a[2..].to_string()); }
        else if a=="-t" || a=="--time" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--time <TIME>' but none was supplied"); std::process::exit(2); }
            cli.time=Some(args[i].clone());
        } else if a.starts_with("--time=") { cli.time=Some(a.splitn(2,'=').nth(1).unwrap().to_string()); }
        else if a.starts_with("-t") && a.len()>2 { cli.time=Some(a[2..].to_string()); }
        else if a=="-a" || a=="--all" { cli.all=true; }
        else if a=="--no-name-check" { cli.no_name_check=true; }
        else if a=="-o" || a=="--output" {
            i+=1;
            if i>=args.len() { eprintln!("error: a value is required for '--output <OUTPUT>' but none was supplied"); std::process::exit(2); }
            let v=&args[i];
            match v.parse::<Output>() {
                Ok(o)=>cli.output=o,
                Err(e)=>{ eprintln!("error: invalid value '{}' for '--output <OUTPUT>': {}", v, e); std::process::exit(2); }
            }
        } else if a.starts_with("--output=") {
            let v=a.splitn(2,'=').nth(1).unwrap();
            match v.parse::<Output>() {
                Ok(o)=>cli.output=o,
                Err(e)=>{ eprintln!("error: invalid value '{}' for '--output <OUTPUT>': {}", v, e); std::process::exit(2); }
            }
        } else if a.starts_with("-o") && a.len()>2 {
            let v=&a[2..];
            match v.parse::<Output>() {
                Ok(o)=>cli.output=o,
                Err(e)=>{ eprintln!("error: invalid value '{}' for '--output <OUTPUT>': {}", v, e); std::process::exit(2); }
            }
        } else if a=="--silent-load" { cli.silent_load=true; }
        else if a.starts_with('-') {
            eprintln!("error: unexpected argument '{}' found", a);
            eprintln!("\n  tip: to pass '{}' as a value, use '-- {}'", a, a);
            eprintln!("\nUsage: executable [OPTIONS] [FILES]...");
            std::process::exit(2);
        } else { cli.files.push(a); }
        i+=1;
    }
    Ok(cli)
}

fn main() {
    let cli = match parse_cli() { Ok(c)=>c, Err(e)=>{ eprintln!("{}",e); std::process::exit(2); } };

    let length_level: usize = match cli.length.parse() {
        Ok(v)=>v,
        Err(_) => {
            eprintln!("error: invalid value '{}' for '--length <LENGTH>': invalid digit found in string", cli.length);
            std::process::exit(2);
        }
    };

    let fields_vec = parse_fields_input(&cli.fields).unwrap_or_else(|e| print_error_and_exit(e));

    let date_filter = if let Some(ref pat)=cli.date { match parse_date_filter(pat) { Ok(f)=>Some(f), Err(e)=>print_error_and_exit(e)} } else {None};
    let time_filter = if let Some(ref pat)=cli.time { match parse_time_filter(pat) { Ok(f)=>Some(f), Err(e)=>print_error_and_exit(e)} } else {None};
    let status_filter = if let Some(ref pat)=cli.status { match parse_status_filter(pat) { Ok(f)=>Some(f), Err(e)=>print_error_and_exit(e)} } else {None};
    let ip_filter = if let Some(ref pat)=cli.ip {
        match compile_str_filter(pat) {
            Ok(sf)=> Some(Box::new(move |e: &LogEntry| sf.eval(&e.remote_addr)) as Box<dyn Fn(&LogEntry)->bool>),
            Err(e)=> print_error_and_exit(e),
        }
    } else {None};
    let method_filter = if let Some(ref pat)=cli.method { match parse_method_filter(pat) { Ok(f)=>Some(f), Err(e)=>print_error_and_exit(e)} } else {None};
    let path_filter = if let Some(ref pat)=cli.path {
        match compile_str_filter(pat) {
            Ok(sf)=> Some(Box::new(move |e: &LogEntry| sf.eval(&e.path)) as Box<dyn Fn(&LogEntry)->bool>),
            Err(e)=> print_error_and_exit(e),
        }
    } else {None};
    let referer_filter = if let Some(ref pat)=cli.referer {
        match compile_str_filter(pat) {
            Ok(sf)=> Some(Box::new(move |e: &LogEntry| sf.eval(&e.referer)) as Box<dyn Fn(&LogEntry)->bool>),
            Err(e)=> print_error_and_exit(e),
        }
    } else {None};

    let file_paths = match collect_file_paths(&cli.files, cli.no_name_check) {
        Ok(v)=>v,
        Err(e)=> {
            if let MyError::PathNotFound(ref p)=e { if p=="/var/log/nginx" {
                eprintln!("No nginx log found at default location, do you have nginx set up?");
                eprintln!("If necessary, provide the path to the log file(s) as argument.");
                eprintln!("More information with 'rhit --help'.");
            }}
            print_error_and_exit(e);
        }
    };

    struct FileGroup { first_date: Option<NaiveDate>, entries: Vec<LogEntry> }

    let mut groups: Vec<FileGroup>=Vec::new();
    for path in &file_paths {
        let lines = match read_file_lines(path) {
            Ok(l)=>l,
            Err(e)=> print_error_and_exit(e),
        };
        let mut entries = Vec::new();
        for line in lines {
            if let Some(entry)=parse_log_line(&line) {
                entries.push(entry);
            }
        }
        if entries.is_empty() { continue; }
        let first_date = entries.first().map(|e| e.date);
        groups.push(FileGroup{first_date, entries});
    }

    if groups.is_empty() {
        print_error_and_exit(MyError::NoLogFileFound);
    }

    groups.sort_by(|a,b| match (a.first_date, b.first_date) {
        (Some(ad), Some(bd)) => ad.cmp(&bd),
        (Some(_), None) => std::cmp::Ordering::Less,
        (None, Some(_)) => std::cmp::Ordering::Greater,
        (None, None) => std::cmp::Ordering::Equal,
    });

    let mut all_entries: Vec<LogEntry> = Vec::new();
    for g in &groups { all_entries.extend(g.entries.clone()); }

    let total_hits_before = all_entries.len();
    let total_bytes_before: u64 = all_entries.iter().map(|e| e.bytes).sum();
    let mut dates_before: Vec<NaiveDate> = all_entries.iter().map(|e| e.date).collect();
    dates_before.sort();
    dates_before.dedup();
    let first_date_before = dates_before.first().cloned().unwrap_or_else(|| NaiveDate::from_ymd_opt(1970,1,1).unwrap());
    let last_date_before = dates_before.last().cloned().unwrap_or(first_date_before);

    let mut filtered = all_entries.clone();
    let mut filter_msgs: Vec<String> = Vec::new();

    macro_rules! apply_filter {
        ($filter_opt:expr, $pat_opt:expr, $label:expr) => {
            if let Some(ref f) = $filter_opt {
                let before = filtered.len();
                filtered.retain(|e| f(e));
                let after = filtered.len();
                if before != after {
                    let pct = (before - after) as f64 / before as f64 * 100.0;
                    filter_msgs.push(format!("Filtering by {} on pattern {} removed {:.2}% of total lines", $label, $pat_opt.as_ref().unwrap(), pct));
                }
            }
        };
    }

    apply_filter!(date_filter, cli.date, "date");
    apply_filter!(ip_filter, cli.ip, "remote address");
    apply_filter!(method_filter, cli.method, "method");
    apply_filter!(path_filter, cli.path, "path");
    apply_filter!(referer_filter, cli.referer, "referer");
    apply_filter!(status_filter, cli.status, "status");
    apply_filter!(time_filter, cli.time, "time");

    match cli.output {
        Output::Raw => {
            for e in &filtered { println!("{}", e.raw_line); }
        },
        Output::Csv => {
            println!("date,time,remote address,method,path,status,bytes sent,referer");
            for e in &filtered {
                let path_escaped = e.path.replace('"', "\"\"");
                let referer_escaped = e.referer.replace('"', "\"\"");
                println!("{},{},{},{},\"{}\",{},{},\"{}\"", e.date_str, e.time_str, e.remote_addr, e.method, path_escaped, e.status, e.bytes, referer_escaped);
            }
        },
        Output::Json => {
            let mut objs = Vec::new();
            for e in &filtered {
                let obj = serde_json::json!({
                    "date": e.date_str,
                    "time": e.time_str,
                    "remote_addr": e.remote_addr,
                    "method": e.method,
                    "path": e.path,
                    "status": format!("{}", e.status),
                    "bytes_sent": e.bytes,
                    "referer": e.referer,
                });
                objs.push(obj);
            }
            println!("{}", serde_json::to_string_pretty(&objs).unwrap());
        },
        Output::Tables => {
            let hits_fmt = format_number(total_hits_before);
            let bytes_fmt = format_bytes(total_bytes_before);
            let first_s = first_date_before.format("%Y/%m/%d").to_string();
            let last_s = last_date_before.format("%Y/%m/%d").to_string();
            println!("{} hits and {} from {} to {}", hits_fmt, bytes_fmt, first_s, last_s);
            for msg in &filter_msgs { println!("{}", msg); }
            if !filter_msgs.is_empty() {
                let fh = filtered.len();
                let fb: u64 = filtered.iter().map(|e| e.bytes).sum();
                println!(" ==> hits: {}, bytes sent: {}", format_number(fh), format_bytes(fb));
                if fh==0 { return; }
            }
            let mut ordered_dates: Vec<NaiveDate> = Vec::new();
            let mut seen = std::collections::HashSet::new();
            for e in &filtered { if seen.insert(e.date) { ordered_dates.push(e.date); } }
            let mut date_map: BTreeMap<NaiveDate,(usize,u64)>=BTreeMap::new();
            for e in &filtered {
                let entry=date_map.entry(e.date).or_insert((0,0));
                entry.0+=1;
                entry.1+=e.bytes;
            }
            for field in &fields_vec {
                match field {
                    Field::Date => { print_date_table(&ordered_dates, &date_map, &cli); },
                    Field::Time => { print_time_table(&filtered, &cli); },
                    Field::Method => { print_method_table(&filtered, &cli, length_level); },
                    Field::Status => { print_status_table(&filtered, &cli, length_level); },
                    Field::Ip => { print_ip_table(&filtered, &cli, length_level); },
                    Field::Ref => { print_ref_table(&filtered, &cli, length_level); },
                    Field::Path => { print_path_table(&filtered, &cli, length_level); },
                }
            }
        }
    }
}
