fn print_status_table(entries: &[LogEntry], cli: &SimpleCli, length_level: usize, ordered_dates: &[NaiveDate]) {
    let mut map: HashMap<u16,(usize,u64,BTreeMap<NaiveDate,f64>)>=HashMap::new();
    for e in entries {
        let entry=map.entry(e.status).or_insert((0,0,BTreeMap::new()));
        entry.0+=1;
        entry.1+=e.bytes;
        let day_val = match cli.key { Key::Hits=>1.0, Key::Bytes=>e.bytes as f64 };
        let dentry=entry.2.entry(e.date).or_insert(0.0);
        *dentry+=day_val;
    }
    let total=entries.len();
    let mut items: Vec<(u16,usize,u64,BTreeMap<NaiveDate,f64>)>=map.into_iter().map(|(c,(h,b,dm))| (c,h,b,dm)).collect();
    items.sort_by(|a,b| match cli.key { Key::Hits=>b.1.cmp(&a.1), Key::Bytes=>b.2.cmp(&a.2) });
    if length_level==0 {
        let mut cat: HashMap<&str,usize>=HashMap::new();
        cat.insert("2xx",0); cat.insert("3xx",0); cat.insert("4xx",0); cat.insert("5xx",0);
        for (code,hits,_,_) in &items {
            let key=match code {200..=299=>"2xx",300..=399=>"3xx",400..=499=>"4xx",500..=599=>"5xx",_=>continue};
            *cat.get_mut(key).unwrap()+=hits;
        }
        println!("HTTP status codes:");
        println!("┌─────┬────┬─────┬────┐");
        println!("│ 2xx │3xx │ 4xx │5xx │");
        println!("├─────┼────┼─────┼────┤");
        let tot=total as f64;
        let p2=*cat.get("2xx").unwrap() as f64 / tot *100.0;
        let p3=*cat.get("3xx").unwrap() as f64 / tot *100.0;
        let p4=*cat.get("4xx").unwrap() as f64 / tot *100.0;
        let p5=*cat.get("5xx").unwrap() as f64 / tot *100.0;
        println!("│{:>4.1}%│{:>4.1}%│{:>4.1}%│{:>4.1}%│", p2,p3,p4,p5);
        println!("└─────┴────┴─────┴────┘");
    } else {
        let show_days = ordered_dates.len()>=4;
        if show_days {
            println!("HTTP status codes");
            println!("┌──────┬────┬──────┬─────┬────┬─────┐");
            println!("│status│hits│  %   │bytes│days│trend│");
            println!("├──────┼────┼──────┼─────┼────┼─────┤");
            let limit=100;
            let disp=if items.len()>limit {&items[..limit]} else {&items[..]};
            for (code,hits,bytes,daymap) in disp {
                let pct=*hits as f64 / total as f64 *100.0;
                let mut vals = Vec::new();
                for d in ordered_dates { vals.push(*daymap.get(d).unwrap_or(&0.0)); }
                let spark = make_sparkline(&vals);
                println!("│{:<6}│{:>4}│{:>5.1}%│{:>5}│{}│     │", code, format_number(*hits), pct, format_bytes(*bytes), spark);
            }
            println!("└──────┴────┴──────┴─────┴────┴─────┘");
        } else {
            println!("{} HTTP status codes. ", items.len());
            println!("┌───┬──────┬────┬─────┬─────┐");
            println!("│ # │status│hits│  %  │bytes│");
            println!("├───┼──────┼────┼─────┼─────┤");
            let limit=100;
            let disp=if items.len()>limit {&items[..limit]} else {&items[..]};
            for (idx,(code,hits,bytes,_)) in disp.iter().enumerate() {
                let pct=*hits as f64 / total as f64 *100.0;
                println!("│{:>3}│{:<6}│{:>4}│{:>4.1}%│{:>5}│", idx+1, code, format_number(*hits), pct, format_bytes(*bytes));
            }
            println!("└───┴──────┴────┴─────┴─────┘");
        }
    }
}

